//! Commands the frontend calls. Typed bindings are generated by tauri-specta.
//!
//! These are thin: parameter marshalling and a call into a crate. Anything
//! resembling logic belongs in a crate where it can be tested.

use crate::AppState;
use aloud_store::{history::Entry, timings::Span, Settings, Stats};
use tauri::{AppHandle, State};
use tauri_specta::Event;

/// Commands must return a `Result` the frontend can read; anyhow's error is
/// not serializable, so errors cross the boundary as strings.
type CmdResult<T> = Result<T, String>;

fn to_string_err<T>(result: anyhow::Result<T>) -> CmdResult<T> {
    result.map_err(|e| format!("{e:#}"))
}

#[tauri::command]
#[specta::specta]
pub fn get_settings(state: State<'_, AppState>) -> Settings {
    state.settings.lock().map(|s| s.clone()).unwrap_or_default()
}

/// Persists settings and applies them to the running app.
#[tauri::command]
#[specta::specta]
pub fn update_settings(
    app: tauri::AppHandle,
    state: State<'_, AppState>,
    settings: Settings,
) -> CmdResult<()> {
    to_string_err(settings.save())?;

    // Into the live config the listener reads, so a rebind takes effect on the
    // next key event rather than at next launch.
    if let Ok(mut config) = state.hotkey_config.lock() {
        *config = settings.hotkeys.clone();
    }

    crate::tray::set_visible(&app, settings.show_menu_bar_icon);

    let mut current = state
        .settings
        .lock()
        .map_err(|_| "settings lock poisoned")?;
    let browsers_changed = current.browser_media != settings.browser_media;
    *current = settings;
    drop(current);
    if browsers_changed {
        // Now Playing should show or drop the browser tab now, not at the next tick.
        crate::media::poll_now();
    }
    Ok(())
}

#[tauri::command]
#[specta::specta]
pub fn get_stats(state: State<'_, AppState>) -> StatsView {
    let stats = state.pipeline.stats();
    StatsView {
        time_saved_seconds: stats.time_saved_seconds(),
        stats,
    }
}

/// [`Stats`] plus the values derived from it. Derived here rather than stored
/// or re-derived in TS, so the formula has exactly one home.
#[derive(serde::Serialize, specta::Type)]
#[serde(rename_all = "camelCase")]
pub struct StatsView {
    #[serde(flatten)]
    pub stats: Stats,
    pub time_saved_seconds: f64,
}

#[tauri::command]
#[specta::specta]
pub fn search_notes(query: String) -> CmdResult<Vec<aloud_notes::SearchResult>> {
    let dir = to_string_err(aloud_notes::directory())?;
    Ok(aloud_notes::search(&query, &aloud_notes::all_notes(&dir)))
}

/// Newest notes, for the empty-query state.
#[tauri::command]
#[specta::specta]
pub fn recent_notes(limit: u32) -> CmdResult<Vec<aloud_notes::Note>> {
    let dir = to_string_err(aloud_notes::directory())?;
    let mut notes = aloud_notes::all_notes(&dir);
    notes.truncate(limit as usize);
    Ok(notes)
}

/// The shipped cleanup prompt and the date it last changed. `version` is what
/// `Settings::seen_prompt_version` is compared against, to tell a user who
/// forked the prompt that they are missing an improvement.
#[derive(serde::Serialize, specta::Type)]
#[serde(rename_all = "camelCase")]
pub struct DefaultPrompt {
    pub text: String,
    pub version: String,
}

#[tauri::command]
#[specta::specta]
pub fn default_prompt() -> DefaultPrompt {
    DefaultPrompt {
        text: aloud_llm::prompts::CLEANUP.to_string(),
        version: aloud_llm::prompts::CLEANUP_VERSION.to_string(),
    }
}

/// Runs a prompt against a sample without a dictation, for the Prompts pane.
/// Everything but the prompt comes from live settings, so this shows what the
/// next dictation would do.
#[tauri::command]
#[specta::specta]
pub async fn test_prompt(
    state: State<'_, AppState>,
    prompt: String,
    sample: String,
) -> CmdResult<String> {
    let settings = state.settings.lock().map(|s| s.clone()).unwrap_or_default();

    if sample.trim().is_empty() {
        return Err("Type a sample transcript to run the prompt against.".into());
    }
    if aloud_llm::cleanup::is_too_short(&sample) {
        // Worded for both callers: the Run Log retries a stored transcript it
        // cannot lengthen, so "add a few more words" is advice it cannot take.
        return Err(format!(
            "Too short to clean up. Dictations of {} words or fewer skip cleanup entirely \
             and are pasted as spoken, so the prompt never runs on them.",
            aloud_llm::cleanup::MIN_WORDS
        ));
    }
    if settings.groq_api_key.trim().is_empty() {
        return Err("No API key is configured, so there is nothing to run against.".into());
    }

    let options = aloud_llm::cleanup::Options {
        api_key: &settings.groq_api_key,
        base_url: &settings.base_url,
        model: &settings.post_processing_model,
        fallback: Some(settings.fallback_model.as_str()),
        custom_prompt: &prompt,
        vocabulary: &settings.vocabulary,
        preserve: &settings.preserve_phrases,
        // Neither caller is a live dictation, so the window in front now does
        // not describe the moment being tested.
        output_language: &settings.output_language,
        instruction_guard: settings.instruction_guard_enabled,
    };
    // An empty result stays an empty string: the Run Log's retry writes this
    // back into the user's transcript, so a sentence here becomes their text.
    to_string_err(aloud_llm::cleanup::clean(options, &sample).await)
}

